import {captureCachedBossEmission} from './boss-emission-materials.js';
import{creatureBuilder,paintCreatureMesh}from'./dungeon-creature-mesh.js';
export const RABBIT_MATERIALS=Object.freeze({fur:['#ffffe0','#c4ccc7','#8394a6'],pink:['#f27f72','#e77988','#ba4a54'],orange:['#ed9353','#f06c1a','#9c3824'],green:['#a2e66f','#5dae27','#1d3926'],soil:['#913f39','#543545','#3d2839'],dark:['#5c627d','#374252','#161928'],gold:['#ffd95a','#e97c07','#9c3824']});
const{fur:W,pink:P,orange:O,green:G,soil:T,dark:D,gold:Y}=RABBIT_MATERIALS,TAU=Math.PI*2,clamp=n=>Math.max(0,Math.min(1,n)),ease=n=>{n=clamp(n);return n*n*(3-2*n);},pivot=[-22,0,26],tip=[-32,25,4],yaws={down:0,left:Math.PI/2,up:Math.PI,right:-Math.PI/2};
const rx=(p,h,a)=>{const y=p[1]-h[1],z=p[2]-h[2];return[p[0],h[1]+y*Math.cos(a)-z*Math.sin(a),h[2]+y*Math.sin(a)+z*Math.cos(a)];};
const rz=(p,h,a)=>{const x=p[0]-h[0],z=p[2]-h[2];return[h[0]+x*Math.cos(a)-z*Math.sin(a),p[1],h[2]+x*Math.sin(a)+z*Math.cos(a)];};
export const RABBIT_CONTACT_ANGLE=(()=>{let lo=-.6,hi=0;for(let i=0;i<45;i++){const a=(lo+hi)/2;if(rx(tip,pivot,a)[2]<0)lo=a;else hi=a;}return(lo+hi)/2;})();
export function polishedPose(b,beat,{soft=false,hit=0,cue=null}={}){const w=b.windup,m=b.rabbitMutiny,open=m?.impactApplied&&beat>=m.impactBeat&&beat<=b.rabbitWindowUntil;let arm=0,state='idle',swing=0;
 if(w){const age=beat-w.startedBeat,left=w.beat-beat;state='windup';arm=2.15*ease(age/.65);if(left<=.22){state='strike';swing=1-ease(left/.22);arm=2.15+(RABBIT_CONTACT_ANGLE-2.15)*swing;}}
 else if(cue){const age=beat-cue.scheduledBeat;if(age>=0&&age<.65){state='impact';arm=RABBIT_CONTACT_ANGLE+(0-RABBIT_CONTACT_ANGLE)*ease((age-.12)/.53);swing=1;}}
 if(open){state='stunned';arm=.2+(soft?0:Math.sin(beat*Math.PI)*.05);}
 return{state,armAngle:arm,swing,headRoll:soft?0:open?Math.sin(beat*Math.PI)*.065:hit?Math.sin(hit*20)*.04:Math.sin(beat*Math.PI/2)*.018,headNod:soft?0:open?.07:state==='windup'?-.04:state==='impact'?.06:0,earLeft:soft?0:Math.sin(beat*Math.PI/2)*.045,earRight:soft?0:Math.sin(beat*Math.PI/2+1.1)*.04,blink:!open&&(Math.floor(beat*8)%71===0||Math.floor(beat*8)%113===0),stunned:!!open,hit,soft};}
function ball(m,id,x,y,rings,ramp,n=10){const a=rings.map(([rx,ry,z])=>Array.from({length:n},(_,i)=>[x+Math.cos(i*TAU/n)*rx,y+Math.sin(i*TAU/n)*ry,z]));for(let k=0;k<a.length-1;k++)for(let i=0;i<n;i++){const j=(i+1)%n;m.face(id,[a[k][i],a[k][j],a[k+1][j],a[k+1][i]],ramp);}m.face(id,a.at(-1),ramp);m.face(id,[...a[0]].reverse(),ramp);}
let rests={};
export function rabbitRestMesh(kind='boss'){if(rests[kind])return rests[kind];const m=creatureBuilder({soft:true,includeHidden:true});
 ball(m,'torso',0,-3,[[13,10,5],[19,13,12],[17,12,24],[10,8,28]],W);m.box('belly',0,8,10,20,9,17,W,2);
 m.box('head',0,0,23,46,33,30,W,4);for(const side of[-1,1]){const x=side*13;m.box('ear-'+side,x,-3,48,13,13,29+(side<0?3:0),W,2.4);m.box('ear-in-'+side,x,3.7,52,6.2,1.2,21+(side<0?3:0),P,.25);m.box('cheek-'+side,side*7,17,24,14,10,12,W,2.3);m.box('tooth-'+side,side*2.8,23,19,4.5,3.7,8,W,.7);m.box('foot-'+side,side*11,9,0,14,15,8,W,2);}
 m.face('nose',[[-4,22.3,33],[4,22.3,33],[0,25.2,28]],P);m.box('mouth',0,23,24,1.2,1.2,4,D,.2);
 for(const side of[-1,1]){const x=side*11;m.box('eye-'+side,x,17.1,39,5.1,1.2,5.8,[D[2],D[2],D[2]],.6);m.box('eye-glint-'+side,x-1,17.85,42.5,.8,.5,1,W,.1);if(kind==='boss')m.face('brow-'+side,[[x-4,17.9,47-side],[x+4,17.9,47+side],[x+4,17.9,45+side],[x-4,17.9,45-side]],[D[1],D[1],D[1]]);}
 if(kind==='boss'){
  m.box('arm-upper',-25,2,25,14,13,16,W,2.4);m.box('arm-fore',-31,13,34,12,15,14,W,2.2);m.box('mitten',-32,25,43,13,13,12,W,2.5);m.box('thumb',-24.8,26,45,5,7,7,W,1.4);
  m.box('stem',-32,25,38,5,5,20,G,1);m.box('leaf-a',-37,25,53,8,6,13,G,1.3);m.box('leaf-b',-28,25,54,7,6,16,G,1.3);
  const n=8,base=Array.from({length:n},(_,i)=>[-32+Math.cos(i*TAU/n)*12,25+Math.sin(i*TAU/n)*10,39]),mid=base.map(([x,y])=>[-32+(x+32)*.76,25+(y-25)*.76,17]);m.face('carrot-top',base,O);for(let i=0;i<n;i++){const j=(i+1)%n;m.face('carrot-shoulder',[base[i],base[j],mid[j],mid[i]],O);m.face('carrot-tip',[mid[i],mid[j],tip],O);}
 }else for(const side of[-1,1])m.box('little-paw-'+side,side*20,9,12,10,12,12,W,2);
 rests[kind]=m.finish();return rests[kind];}
const armPart=id=>/^(arm-|mitten|thumb|stem|leaf-|carrot-)/.test(id),headPart=id=>/^(head|ear-|cheek-|tooth-|eye-|nose|mouth|brow-)/.test(id);
const ramp=id=>id.startsWith('carrot')?O:/^(stem|leaf)/.test(id)?G:id.startsWith('ear-in')||id==='nose'?P:/^(eye-(?!glint)|brow|mouth)/.test(id)?[D[2],D[2],D[2]]:W;
export function clipGround(points){const a=[];for(let i=0;i<points.length;i++){const p=points[i],q=points[(i+1)%points.length],x=p[2]>=0,y=q[2]>=0;if(x)a.push(p);if(x!==y){const t=p[2]/(p[2]-q[2]);a.push([p[0]+(q[0]-p[0])*t,p[1]+(q[1]-p[1])*t,0]);}}return a;}
export function polishedRabbitMesh({kind='boss',direction='down',pose={},emergence=0,includeHidden=false}={}){const m=creatureBuilder({direction,soft:true,includeHidden}),burial=kind==='child'?18*(1-clamp(emergence)):0;for(const f of rabbitRestMesh(kind)){if(kind==='boss'&&/^(foot|belly)/.test(f.id))continue;if(pose.blink&&f.id.startsWith('eye-glint'))continue;let points=f.points.map(p=>{p=[...p];if(kind==='boss'&&armPart(f.id))p=rx(p,pivot,pose.armAngle||0);if(headPart(f.id)){if(f.id.startsWith('ear-')){const side=f.id.endsWith('--1')?-1:1;p=rx(p,[side*13,-3,48],side<0?pose.earLeft||0:pose.earRight||0);}p=rx(p,[0,0,25],pose.headNod||0);p=rz(p,[0,0,25],pose.headRoll||0);}if(pose.blink&&f.id.startsWith('eye-')&&!f.id.startsWith('eye-glint'))p[2]=42+(p[2]-42)*.15;p[2]-=burial;return p;});points=clipGround(points);if(points.length>=3)m.face(f.id,points,ramp(f.id));}for(const f of m.faces)if(/^(eye|nose|mouth|brow)/.test(f.id))f.depth+=3;return m.finish();}
export function weaponTip(pose={},direction='down'){const p=rx(tip,pivot,pose.armAngle||0),a=yaws[direction]||0;return[p[0]*Math.cos(a)-p[1]*Math.sin(a),p[0]*Math.sin(a)+p[1]*Math.cos(a),p[2]];}
const frames=new Map();export const rabbitPolishedCache=()=>frames.size;
function samplePose(pose){return Object.fromEntries(Object.entries(pose).filter(([k])=>!['state','swing','hit','soft'].includes(k)).map(([k,v])=>[k,typeof v==='number'?Math.round(v*48)/48:v]));}
export function paintPolishedRabbit(c,{kind='boss',x=0,y=0,width=92,direction='down',pose={},emergence=0,detail=false}={}){const k=width/94,q=samplePose(pose),u=Math.round(emergence*24)/24,key=JSON.stringify([kind,direction,q,u]);if(detail){paintCreatureMesh(c,polishedRabbitMesh({kind,direction,pose,emergence}),x,y,k,{shadow:kind==='boss',emissionIndex:kind==='boss'?6:null});return true;}let image=frames.get(key);if(!image){const density=kind==='boss'?3:1.5;image=new OffscreenCanvas(180*density,140*density);const g=image.getContext('2d');g.scale(density,density);paintCreatureMesh(g,polishedRabbitMesh({kind,direction,pose:q,emergence:u}),90,110,1,{shadow:kind==='boss',emissionIndex:kind==='boss'?6:null});if(frames.size>=40){const old=frames.keys().next().value;frames.get(old).width=1;frames.delete(old);}frames.set(key,image);}c.drawImage(image,x-90*k,y-110*k,180*k,140*k);captureCachedBossEmission(c,image,x-90*k,y-110*k,180*k,140*k,x,y);return true;}
let hole;
export function polishedBurrowMesh(){if(hole)return hole;const m=creatureBuilder({soft:true});for(let i=0;i<12;i++){const a=i*TAU/12,b=(i+1)*TAU/12,p=(a,r,z)=>[Math.cos(a)*r,Math.sin(a)*r*.7,z];m.face('earth-rim',[p(a,35,0),p(b,35,0),p(b,29,6),p(a,29,6)],T);m.face('earth-top',[p(a,29,6),p(b,29,6),p(b,22,2),p(a,22,2)],T);m.face('earth-inner',[p(a,22,2),p(b,22,2),p(b,22,-3),p(a,22,-3)],[T[1],T[2],D[2]]);}hole=m.finish();return hole;}
export function paintPolishedBurrow(c,{x,y,width=92,foreground=false}={}){const k=width/94;if(!foreground){c.save();c.fillStyle=D[2];c.beginPath();c.ellipse(x,y,22*k,15*k,0,0,TAU);c.fill();c.restore();paintCreatureMesh(c,polishedBurrowMesh(),x,y,k,{shadow:false});}else{const faces=polishedBurrowMesh().filter(f=>f.points.reduce((s,p)=>s+p[1],0)>0);paintCreatureMesh(c,faces,x,y,k,{shadow:false});}}
export function paintSwingTrail(c,{x,y,width=92,direction='down',pose,soft=false}){if(soft||!['strike','impact'].includes(pose.state))return;const k=width/94,points=[];for(let i=0;i<6;i++){const a=pose.armAngle+i*.16,p=weaponTip({armAngle:a},direction);points.push([x+(p[0]+p[1]/11)*k,y+(p[1]*8/11-p[2])*k]);}c.save();c.lineCap='round';c.lineJoin='round';c.strokeStyle=O[0];c.globalAlpha=.38;c.lineWidth=5*k;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();c.strokeStyle=Y[0];c.lineWidth=1.3*k;c.globalAlpha=.65;c.stroke();c.restore();}
export function paintDizzy(c,x,y,width,beat,soft=false){const k=width/94;for(let i=0;i<3;i++){const a=(soft?0:beat*.9)+i*TAU/3,xx=x+Math.cos(a)*17*k,yy=y-82*k+Math.sin(a)*4*k;c.save();c.translate(xx,yy);c.rotate(soft?0:-beat*.7);c.fillStyle=Y[0];c.strokeStyle=Y[1];c.lineWidth=1*k;c.beginPath();for(let j=0;j<10;j++){const r=(j%2?1.5:3.8)*k,t=j*Math.PI/5-Math.PI/2;j?c.lineTo(Math.cos(t)*r,Math.sin(t)*r):c.moveTo(Math.cos(t)*r,Math.sin(t)*r);}c.closePath();c.fill();c.stroke();c.restore();}}
export function strikeDirt(cue,beat,soft=false){const age=beat-cue.scheduledBeat;if(age<0||age>.75)return[];const u=age/.75;return Array.from({length:soft?4:14},(_,i)=>{const a=i*2.399963+cue.target.x*.1,size=2+i%3;return{x:Math.cos(a)*(12+i%4*5)*u,y:Math.sin(a)*(10+i%4*3)*u,z:Math.sin(u*Math.PI)*(soft?8:15+i%4*4),size,alpha:1-u};});}
export function strikeAnchors(cue,project){const p=project(cue.origin.x,cue.origin.y),q=project(cue.target.x,cue.target.y),t=weaponTip({armAngle:RABBIT_CONTACT_ANGLE},cue.direction),k=92/94;return{from:{x:p.x/2+(t[0]+t[1]/11)*k,y:p.y/2+t[1]*8/11*k},to:{x:q.x/2,y:q.y/2}};}
export function paintRabbitStrikeFx(c,cue,beat,project,soft=false){if(!cue)return;const parts=strikeDirt(cue,beat,soft);if(!parts.length)return;const g=project(cue.target.x,cue.target.y),x=g.x/2,y=g.y/2,m=creatureBuilder({soft:true}),age=beat-cue.scheduledBeat;if(!soft&&age<.25&&cue.origin){const a=strikeAnchors(cue,project);c.save();c.globalAlpha=(1-age/.25)*.28;c.strokeStyle=O[0];c.lineWidth=2;c.lineCap='round';c.beginPath();c.moveTo(a.from.x,a.from.y);c.quadraticCurveTo((a.from.x+x)/2,(a.from.y+y)/2-4,x,y);c.stroke();c.restore();}for(const p of parts)m.box('dirt',p.x,p.y,p.z,p.size,p.size,p.size*.8,T,.5);c.save();c.globalAlpha=parts[0].alpha;paintCreatureMesh(c,m.finish(),x,y,1,{shadow:true});c.restore();}
